// Up to MAX waiting leads per run. If the same email appears twice in one run, only the first
// goes now; the other stays Waiting and is merged into the Odoo lead on the next run.
const MAX = 10;
const PROMPT = "You are a lead qualifier for SunGuard Solar & CCTV, a small solar and CCTV shop in the Philippines (demo business).\nRead the customer message and return ONLY valid JSON, no extra text:\n{\n  \"spam\": true|false,\n  \"score\": \"Hot\"|\"Warm\"|\"Cold\",\n  \"products\": [\"Solar Panel\"|\"Inverter\"|\"Battery\"|\"Hybrid System\"|\"CCTV\"],\n  \"system_size_kw\": number|null,\n  \"monthly_bill_php\": number|null,\n  \"city\": string|null,\n  \"timeline\": string|null,\n  \"summary\": \"one short English sentence\"\n}\nScoring:\n- Hot: clear product or size AND a timeline within 60 days or asks for a quote/site visit.\n- Warm: clear interest but no timeline, or only asking price.\n- Cold: general question, just browsing, or very far timeline.\n- spam: links, ads, nonsense, or unrelated selling.\nRules: The message may be English, Tagalog or Taglish. Do not invent numbers; use null if not stated. Never promise prices or discounts.\nCustomer message:\n\"\"\"{{message}}\"\"\"";
const seen = new Set();
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  const leadId = String(r.Lead_ID || '').trim();
  if (!leadId || String(r.Status || '').trim() !== 'Waiting') continue;
  if (out.length >= MAX) break;
  const lead = { Lead_ID: leadId, Name: String(r.Name || '').trim(), Email: String(r.Email || '').trim().toLowerCase(),
                 Phone: String(r.Phone || '').trim(), City: String(r.City || '').trim(),
                 Message: String(r.Message || '').trim().slice(0, 2000) };
  if (String(r.Consent || '').trim().toLowerCase() !== 'yes') {
    out.push({ json: { route: 'error', lead, error: 'no consent' } });
    continue;
  }
  if (lead.Email && seen.has(lead.Email)) continue;
  if (lead.Email) seen.add(lead.Email);
  const safeMsg = lead.Message.replace(/"{3}/g, '"');
  const text = PROMPT.replace('{{message}}', () => safeMsg);
  out.push({ json: { route: 'ai', lead,
    geminiRequest: { contents: [{ parts: [{ text }] }],
                     generationConfig: { responseMimeType: 'application/json', temperature: 0.1 } } } });
}
return out;

const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) {
  throw new Error('Odoo config not found. Run odoo_setup_crm.py --apply and check ODOO_* env vars. ' +
    JSON.stringify(cfgRes.error || '').slice(0, 300));
}
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };
const errText = (e) => (e && (e.data?.message || e.message)) || JSON.stringify(e || '').slice(0, 200);

// One output item per lead. Gemini HTTP error (503/429): skipped, stays Waiting, retried next run.
const ALLOWED = ['Solar Panel', 'Inverter', 'Battery', 'Hybrid System', 'CCTV'];
const src = $('Consent = Yes?').all(0);
const res = $input.all();
const num = (v) => (typeof v === 'number' && isFinite(v) ? v : null);
const out = [];
for (let i = 0; i < res.length; i++) {
  const lead = src[i]?.json?.lead;
  if (!lead) continue;
  const r = res[i].json || {};
  if (r.error) continue;
  const text = (r.candidates || []).flatMap(c => (c.content?.parts || []).map(p => p.text || '')).join('').trim();
  let ai;
  try { ai = JSON.parse(text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')); }
  catch (e) { out.push({ json: { route: 'error', lead, error: 'AI returned invalid JSON' } }); continue; }
  if (ai.spam === true) { out.push({ json: { route: 'spam', lead, ai: { score: '' }, error: 'spam' } }); continue; }
  if (!['Hot', 'Warm', 'Cold'].includes(ai.score)) { out.push({ json: { route: 'error', lead, error: 'AI score missing' } }); continue; }
  ai.products = (Array.isArray(ai.products) ? ai.products : []).filter(p => ALLOWED.includes(p));
  ai.system_size_kw = num(ai.system_size_kw);
  ai.monthly_bill_php = num(ai.monthly_bill_php);
  ai.summary = String(ai.summary || '').slice(0, 300);
  ai.timeline = ai.timeline ? String(ai.timeline).slice(0, 100) : null;
  ai.city = ai.city ? String(ai.city).slice(0, 80) : null;
  const domain = lead.Email ? [['email_from', '=ilike', lead.Email], ['company_id', '=', cfg.company_id]] : [['id', '=', 0]];
  out.push({ json: { route: 'ok', lead, ai,
    rpc: { model: 'crm.lead', method: 'search_read', args: [domain],
           kwargs: { fields: ['id', 'name'], limit: 1, context } } } });
}
return out;

const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) {
  throw new Error('Odoo config not found. Run odoo_setup_crm.py --apply and check ODOO_* env vars. ' +
    JSON.stringify(cfgRes.error || '').slice(0, 300));
}
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };
const errText = (e) => (e && (e.data?.message || e.message)) || JSON.stringify(e || '').slice(0, 200);

// Existing lead with the same email -> add a note (no second lead). Otherwise create a new lead.
const src = $('Valid lead?').all(0);
const res = $input.all();
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const noop = { model: 'res.users', method: 'search', args: [[['id', '=', 0]]], kwargs: {} };
const out = [];
for (let i = 0; i < res.length; i++) {
  const d = src[i].json, r = res[i].json || {};
  const L = d.lead, ai = d.ai;
  if (r.error) { out.push({ json: { ...d, action: 'error', error: 'Odoo search: ' + errText(r.error), rpc: noop } }); continue; }
  const found = (r.result || [])[0];
  const products = ai.products.length ? ai.products.join(' + ') : 'Inquiry';
  const size = ai.system_size_kw ? ` ${ai.system_size_kw}kW` : '';
  const city = ai.city || L.City || 'Unknown city';
  const lines = [
    ['Summary (AI)', ai.summary], ['Products', ai.products.join(', ') || '-'],
    ['System size', ai.system_size_kw ? ai.system_size_kw + ' kW' : '-'],
    ['Monthly bill', ai.monthly_bill_php ? 'PHP ' + ai.monthly_bill_php : '-'],
    ['Timeline', ai.timeline || '-'], ['Score (AI)', ai.score], ['Sheet Lead ID', L.Lead_ID],
    ['Customer message', L.Message]];
  const summary = { products, size, city };
  if (found) {
    const body = `New website inquiry ${L.Lead_ID} (AI score ${ai.score}). ` +
      lines.map(([k, v]) => `${k}: ${v}`).join(' | ');
    out.push({ json: { ...d, ...summary, action: 'note', odoo_id: found.id,
      rpc: { model: 'crm.lead', method: 'message_post', args: [[found.id]],
             kwargs: { body, message_type: 'comment', subtype_xmlid: 'mail.mt_note', context } } } });
  } else {
    const tags = [ai.score, ...ai.products].map(t => cfg.tag_ids[t]).filter(Boolean);
    const vals = {
      name: `${products}${size} – ${city}`, type: 'opportunity',
      contact_name: L.Name, email_from: L.Email, phone: L.Phone, city,
      description: '<ul>' + lines.map(([k, v]) => `<li><b>${esc(k)}:</b> ${esc(v)}</li>`).join('') + '</ul>',
      tag_ids: [[6, 0, tags]], priority: { Hot: '3', Warm: '2', Cold: '1' }[ai.score],
      stage_id: cfg.stage_ids.New, team_id: cfg.team_id, company_id: cfg.company_id,
      source_id: cfg.source_id, medium_id: cfg.medium_id, x_lead_ref: L.Lead_ID };
    out.push({ json: { ...d, ...summary, action: 'create',
      rpc: { model: 'crm.lead', method: 'create', args: [vals], kwargs: { context } } } });
  }
}
return out;

// Sheet update + Telegram text (Hot and Warm only).
const src = $('Decide: create or add note').all();
const res = $input.all();
const errText = (e) => (e && (e.data?.message || e.message)) || JSON.stringify(e || '').slice(0, 200);
const now = new Date().toISOString();
const out = [];
for (let i = 0; i < res.length; i++) {
  const d = src[i].json, r = res[i].json || {};
  const row = { Lead_ID: d.lead.Lead_ID, Score: d.ai?.score || '', Processed_At: now };
  if (d.action === 'error' || r.error) {
    out.push({ json: { ...row, Status: 'Error', Odoo_Lead_ID: '', Error: d.error || 'Odoo: ' + errText(r.error), _alert: '' } });
    continue;
  }
  const odooId = d.action === 'create' ? r.result : d.odoo_id;
  let alert = '';
  if (['Hot', 'Warm'].includes(d.ai.score)) {
    const icon = d.ai.score === 'Hot' ? '🔥' : '🌤️';
    const when = d.ai.timeline ? `, ${d.ai.timeline}` : '';
    alert = d.action === 'create'
      ? `${icon} New ${d.ai.score.toUpperCase()} lead ${d.lead.Lead_ID} — ${d.products}${d.size}, ${d.city}${when}. Odoo #${odooId}`
      : `${icon} ${d.ai.score.toUpperCase()} follow-up ${d.lead.Lead_ID} — same customer as Odoo #${odooId}, note added.`;
  }
  out.push({ json: { ...row, Status: 'Processed', Odoo_Lead_ID: odooId, Error: '', _alert: alert } });
}
return out;

// Spam, no consent or invalid AI answer: mark the row Error so it is not processed again.
const now = new Date().toISOString();
return $input.all().map(it => {
  const d = it.json;
  return { json: { Lead_ID: d.lead?.Lead_ID, Status: 'Error', Score: d.ai?.score || '', Odoo_Lead_ID: '',
                   Processed_At: now, Error: d.error || 'error', _alert: '' } };
});
